import {coreCard,storyPage,storyShelf} from './story-view.mjs';
import {mountStoryPlayer} from './story-player.mjs';
import {createSpeech} from './audio.mjs';
import {KEY,DAY,fresh,normalize,merge,itemStatus,unlocked,shuffle,activeWords,eligibleWords,question,trapQuestion} from './core.mjs';
const $=s=>document.querySelector(s),app=$('#app'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,state=fresh(),session=null,storageFailed=false,view='home',cleanupStory=()=>{};
const names=['基本','中級','応用','発展'];
const btn=(action,label,cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const link=(hash,label,cls='button')=>`<a class="${cls}" href="#${hash}">${label}</a>`;
const prefix=id=>data.prefixes.find(p=>p.id===id);
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.schemaVersion!==1)throw Error('保存形式が異なります');state=normalize(parsed);}}catch{storageFailed=true;}}
function persist(){try{const raw=localStorage.getItem(KEY);if(raw&&JSON.parse(raw).schemaVersion!==1)throw Error('unknown schema');const disk=raw?normalize(JSON.parse(raw)):fresh();state.attempts=merge(state.attempts,disk.attempts);state.seen=[...new Set([...state.seen,...disk.seen])];localStorage.setItem(KEY,JSON.stringify(state));}catch{storageFailed=true;}storageNotice();}
function storageNotice(){if(storageFailed)$('#notice').textContent='この環境では学習記録を保存できません。今の画面で学習を続けられます。';}
function soundUI(){$('#sound').textContent=`♪ 音声 ${state.sound?'ON':'OFF'}`;$('#sound').setAttribute('aria-pressed',String(state.sound));}
const {stop,speak}=createSpeech({host:window,enabled:()=>state.sound,status:s=>$('#audio-status').textContent=s});
document.querySelector('.skip').onclick=e=>{e.preventDefault();app.focus();};
$('#sound').onclick=()=>{state.sound=!state.sound;stop();persist();soundUI();};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
const audio=(word,label='♪ 聞く')=>btn('speak',label,'small',`data-word="${esc(word)}"`);
function effective(w){return {...w,...(data.editorial.words[w.word]?.meaning_ja?{meaning_ja:data.editorial.words[w.word].meaning_ja}:{})};}
function words(){return eligibleWords(data).map(effective);}
function mvpPrefixes(){return data.prefixes.filter(p=>data.mvp.prefix_ids.includes(p.id)).sort((a,b)=>a.order-b.order);}
function can(stage){return unlocked(stage,state.attempts,mvpPrefixes());}
function formula(w){const p=prefix(w.prefix_id);return `<div class="formula"><span class="part" lang="en">${esc(p.form.replace(/-$/,''))}</span><span>＋</span><span class="base" lang="en">${esc(w.base)}</span><span>→</span><span class="whole" lang="en">${esc(w.word)}</span></div>`;}
function explanation(w){const e=data.editorial.words[w.word];return `${formula(w)}<p><strong>${esc(w.meaning_ja)}</strong> ${audio(w.word,'♪ 単語全体を聞く')}</p><p>${esc(w.compositional_hint_ja)}</p>${w.caution_ja?`<p class="warning">${esc(w.caution_ja)}</p>`:''}${e?.note_ja?`<p class="warning">${esc(e.note_ja)}</p>`:''}<p class="muted">パーツは意味を考える手がかり。実際の意味は単語全体で確かめます。</p>`;}
function setView(html){cleanupStory();app.innerHTML=html;storageNotice();app.focus({preventScroll:true});window.scrollTo(0,0);document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.pathname===location.pathname&&(a.hash===location.hash||(a.hash==='#home'&&['stage','lesson','session'].includes(view))))a.setAttribute('aria-current','page');});}
function stories(){return data.stories.stories;}
function seenImage(id){if(!state.seen.includes(id)){state.seen.push(id);persist();const count=$('#seen-count');if(count)count.textContent=state.seen.length;}}
function setupStory(){cleanupStory=mountStoryPlayer(app,{stories:stories(),motion:state.motion,onViewed:seenImage,narrate:text=>speak(text,{lang:'ja-JP',rate:.95}),onMotion:motion=>{state.motion=motion;persist();}});}
function gallery(){setView(`<div class="eyebrow">14の、意味のレンズ</div><h1>イメージの本だな</h1><p class="reader-note">好きなお話からひらこう。絵と動きを見て、その見方を別の単語にも重ねてみよう。</p>${storyShelf(stories(),state.seen)}<p class="muted">「イメージを見た」と、問題に正解した記録は別です。</p>`);}
function home(){const over=stories().find(s=>s.prefix_id==='over_too_much');setView(`<section class="hero"><div><div class="eyebrow">ひとつのイメージが、いくつもの単語へ。</div><h1>接頭辞は、<br>意味を見るレンズ。</h1><p>「こえる」「もどる」「もう一度」。<br>絵の中の動きが、英単語の中にもある。</p><div class="actions">${link('lesson/over_too_much','over- のお話を読む →','button primary')}${link('images','14のイメージを見る')}</div><p class="home-read-note">読むだけで進めます。問題は、ためしたいときに。</p></div><div class="hero-story">${coreCard(over,{compact:true})}</div></section><div class="stats"><span><strong id="seen-count">${state.seen.length}</strong>イメージを見た <small>/14</small></span><span><strong>${state.attempts.length}</strong>取り組んだ問題</span><span><strong>${dueItems().length}</strong>いま復習できる語</span></div><h2>好きなお話を、ひらこう。</h2>${storyShelf(stories(),state.seen)}<h2>4つのステップ</h2><div class="stage-grid">${names.map((name,i)=>{const n=i+1,descs=['8つのイメージを、動く絵本で。','数や上下のイメージを6つ追加。','14項目の組み立て・分解・意味推測。','例外を見て、イメージの限界も知ろう。'];return `<section class="stage"><span class="number">STEP 0${n}</span><h2>${name}</h2><p>${descs[i]}</p>${can(n)?link('stage/'+n,n<=2?'お話を読む →':'ためしてみる →'):`<span class="badge">${n===3?'14項目で各1問正解':'応用で4問正解'}で開く</span>`}</section>`;}).join('')}</div><p class="muted">絵は意味を考える手がかりです。教材は暫定版で、段階は独自の学習順です。</p>`);setupStory();}
function stage(n){if(!can(n)){setView(`<h1>まずは前のステップへ</h1><p>確認問題をためしたいときは、ホームの条件で開きます。絵本は14項目すべて自由に読めます。</p>${link('images','イメージの本だなへ')}`);return;}if(n<=2){const ids=mvpPrefixes().filter(p=>p.stage===n).map(p=>p.id);setView(`${link('home','← 学ぶ','back')}<h1>${names[n-1]}のイメージ</h1><p class="reader-note">接頭辞の動きを見て、単語の場面にも重ねよう。読むだけで、次のお話へ進めます。</p>${storyShelf(stories().filter(s=>ids.includes(s.prefix_id)),state.seen)}`);}else{setView(`${link('home','← 学ぶ','back')}<section class="panel narrow"><div class="eyebrow">STEP 0${n}</div><h1>${names[n-1]}の研究</h1><p>${n===3?'見てきたイメージを手がかりに、まぜて8問をためそう。':'似た文字でも同じ接頭辞とは限りません。イメージで説明できるかを確かめよう。'}</p>${btn('mixed','研究をはじめる','primary',`data-stage="${n}"`)}</section>`);}}
function lesson(id){const story=stories().find(s=>s.prefix_id===id);if(!story)return gallery();const i=stories().indexOf(story);setView(storyPage(story,data,{next:stories()[i+1]||null,stage:prefix(id).stage}));setupStory();}
const modes=['meaning','build','split','infer'];
function makeQuestion(w,mode){const allowed=data.editorial.words[w.word].modes;return question({...data,words:data.words.map(effective)},w,allowed&&!allowed.includes(mode)?allowed[0]:mode);}
function start(qs,stageN,title){stop();session={qs,index:0,stage:stageN,title,answers:[],phase:qs[0]?.mode==='trap'?'question':'base',answered:false};view='session';drawSession();}
function practice(id){const p=prefix(id);if(!p||!can(p.stage))return;const ws=shuffle(words().filter(w=>w.prefix_id===id));const qs=modes.flatMap((m,i)=>{const allowed=ws.filter(w=>!data.editorial.words[w.word].modes||data.editorial.words[w.word].modes.includes(m));return allowed.length?[makeQuestion(allowed[i%allowed.length],m)]:[];});if(qs.length)start(qs,p.stage,p.form+' の研究');}
function mixed(n){if(!can(n))return;if(n===4)start(shuffle(data.editorial.traps).map(trapQuestion),4,'発展・例外の研究');else {const ws=shuffle(words());start(ws.slice(0,8).map((w,i)=>makeQuestion(w,modes[i%4])),3,'応用・まぜて研究');}}
function drawSession(){const s=session,q=s.qs[s.index];if(!q)return result();const w=q.word;let body='';if(s.phase==='base'){body=`<div class="eyebrow">まずは、元のことば</div><h1>このことば、知っている？</h1><p class="question-word" lang="en">${esc(w.base)}</p><div style="text-align:center">${audio(w.base,'♪ 元の単語を聞く')}</div><p>知らないときは「意味を見てみる」で、先に確かめよう。</p>${s.hint?`<div class="feedback"><strong>${esc(data.editorial.words[w.word].base_hint_ja)}</strong></div>`:''}<div class="actions">${btn('know','知っている・問題へ','primary')}${btn('basehint','意味を見てみる')}</div>`;}else{body=`<div class="eyebrow">${({meaning:'接頭辞の意味',build:'単語を組み立てる',split:'単語を分解する',infer:'意味を推測する',trap:'例外を見抜く'})[q.mode]}</div><h1>${esc(q.prompt)}</h1>${q.mode==='trap'?`<p class="question-word" lang="en">${esc(w)}</p>${w!=='unbig'?audio(w):''}`:q.mode==='meaning'?`<p class="question-word part" lang="en">${esc(prefix(q.prefix).form)}</p><p class="muted">例：${esc(w.word)}</p>`:q.mode==='build'?`<div class="formula"><span class="part">${esc(prefix(q.prefix).form.replace(/-$/,''))}</span><span>＋</span><span class="base">${esc(w.base)}</span><span>→ ?</span></div>`:`<p class="question-word" lang="en">${esc(w.word)}</p>${audio(w.word)}`}${q.mode!=='trap'?`<details class="hint"><summary>元のことばのヒント</summary><p><strong lang="en">${esc(w.base)}</strong>：${esc(data.editorial.words[w.word].base_hint_ja)} ${audio(w.base)}</p>${q.mode==='infer'?`<p>${esc(prefix(q.prefix).form)}：${esc(prefix(q.prefix).meaning_ja)}</p>`:''}</details>`:''}<div class="choices">${q.choices.map((c,i)=>btn('answer',esc(c),s.answered?(c===q.answer?'correct':c===s.chosen?'chosen-wrong':''):'',`data-index="${i}" ${s.answered?'disabled':''}`)).join('')}</div>${s.answered?`<div class="feedback" role="status"><h2>${s.chosen===q.answer?'その通り！':'一緒に確かめよう。'}</h2><p>答え：<strong>${esc(q.answer)}</strong></p>${q.mode==='trap'?`<p>${esc(q.explanation)}</p><p class="muted">知らない語は、辞書や文の中で確認しよう。</p>`:explanation(w)}${btn('next',s.index+1===s.qs.length?'研究の結果へ →':'次の研究へ →','primary')}</div>`:''}`;}
 setView(`<div class="narrow"><div class="step"><span>${esc(s.title)}</span><span>${s.index+1} / ${s.qs.length} 問</span></div><progress value="${s.index}" max="${s.qs.length}" aria-label="学習の進み具合"></progress><section class="panel">${body}</section>${link('home','学ぶ画面へ戻る（ここまでの解答は保存済み）','back')}</div>`);
 if(s.answered)app.querySelector('[data-action="next"]')?.focus({preventScroll:true});
}
function answer(i){const s=session;if(!s||s.answered||s.phase!=='question')return;const q=s.qs[s.index],chosen=q.choices[i];if(chosen===undefined)return;s.answered=true;s.chosen=chosen;const a={id:crypto.randomUUID(),item:q.item,prefix:q.prefix,mode:q.mode,stage:s.stage,correct:chosen===q.answer,at:Date.now()};state.attempts.push(a);s.answers.push(a);persist();drawSession();}
function result(){const s=session,score=s.answers.filter(a=>a.correct).length;setView(`<section class="panel narrow"><div class="eyebrow">研究おつかれさま！</div><h1>今日の発見を、次につなげよう。</h1><p class="result-number">${score}<small> / ${s.qs.length}</small></p><p>正解した語は1日・3日・7日と間隔をあけて復習します。間違えた語は10分後から。先に練習しても、復習の予定日は先送りしません。</p>${s.answers.some(a=>!a.correct)?'<p>間違えた語は「復習する」で、今すぐもう一度ためせます。</p>':''}<div class="actions">${link('home','学ぶ画面へ','button primary')}${link('review','復習を見る')}</div><p class="muted">記録はこのブラウザに保存します。ブラウザのデータを消すと記録も消えます。</p></section>`);}
function dueItems(){return [...words().map(w=>({id:w.id,w})),...data.editorial.traps.map(t=>({id:t.id,t}))].filter(x=>itemStatus(state.attempts,x.id).isDue);}
function reviewList(){const entries=[...words().map(w=>({id:w.id,w})),...data.editorial.traps.map(t=>({id:t.id,t}))].map(x=>({...x,status:itemStatus(state.attempts,x.id)})).filter(x=>x.status.attempts);entries.sort((a,b)=>Number(b.status.isDue)-Number(a.status.isDue)||b.status.wrong-a.status.wrong||a.status.due-b.status.due);return entries;}
function records(isReview){const entries=reviewList(),count=state.attempts.length,correct=state.attempts.filter(a=>a.correct).length;setView(`<h1>${isReview?'思い出すと、力になる。':'あなたの学習きろく'}</h1>${!isReview?`<section class="panel"><h2>見てきたイメージ ${state.seen.length} / 14</h2><p class="muted">見た記録です。正解・習得の記録には加えません。</p><div class="actions">${stories().filter(s=>state.seen.includes(s.prefix_id)).map(s=>link('lesson/'+s.prefix_id,esc(s.form)+' '+esc(s.cue_ja),'button small')).join('')||link('images','イメージの本だなへ')}</div></section>`:''}<p>${isReview?'間違えた語を優先し、時間をあけて思い出そう。':'接頭辞ごとのきろくと、単語・例外問題の復習予定です。'}</p><div class="stats"><span><strong>${count}</strong>解答</span><span><strong>${count?Math.round(correct/count*100):0}%</strong>正答率</span><span><strong>${dueItems().length}</strong>復習の時刻</span></div>${entries.length?`<div class="actions">${btn('reviewdue','時刻が来た語を復習','primary',dueItems().length?'':'disabled')}${btn('reviewweak','苦手な語を今すぐ練習','',entries.some(x=>x.status.wrong)?'':'disabled')}${btn('reviewall','取り組んだ語を練習')}</div><p class="muted">同じ語の問題形式を変えて復習します。まだ練習していない語は一覧に含めません。</p>`:'<p class="panel">確認問題のきろくはまだありません。絵本は自由に読めます。</p>'+link('lesson/un_not','はじめの研究へ','button primary')}${!isReview?`<h2>パーツごとのきろく</h2><div class="lesson-list">${mvpPrefixes().map(p=>{const a=state.attempts.filter(a=>a.prefix===p.id);return `<div class="lesson"><strong>${esc(p.form)}</strong> ${esc(p.meaning_ja)}<p>${a.filter(a=>a.correct).length} / ${a.length} 問正解</p></div>`;}).join('')}</div><h2>単語・例外の復習予定</h2>`:''}<div class="panel">${entries.map(x=>`<section class="review-row"><strong lang="en">${esc(x.w?.word||x.t.word)}</strong> ${x.t?'<span class="badge">例外チェック</span>':''} <span class="badge">${x.status.isDue?'復習しよう':`次は ${new Date(x.status.due).toLocaleString('ja-JP')}`}</span><p class="muted">${x.status.attempts}回の解答・${x.status.wrong}回は一緒に確認・復習の連続正解 ${x.status.streak}回</p>${btn('reviewone','この語を練習','small',`data-item="${esc(x.id)}"`)}</section>`).join('')||'<p>研究すると、ここに予定が表示されます。</p>'}</div>`);}
function reviewStart(kind,id){let entries=reviewList();if(kind==='reviewdue')entries=entries.filter(x=>x.status.isDue);if(kind==='reviewweak')entries=entries.filter(x=>x.status.wrong);if(id)entries=entries.filter(x=>x.id===id);if(!entries.length)return;start(entries.slice(0,8).map((x,i)=>x.t?trapQuestion(x.t):makeQuestion(x.w,modes[i%4])),1,'思い出す研究');}
function guide(){const holds=activeWords(data).filter(w=>data.editorial.words[w.word].use==='card');setView(`<h1>使い方と、教材について</h1><section class="panel"><h2>イメージ → 例語 → 別の語へ</h2><p>14項目に固有の動きのイメージを用意しました。下へ読むと絵が一度だけ動きます。「元の絵を見る」「もう一度見る」で見比べられます。「先生のお話」は端末の日本語音声です。「絵でたしかめる」は採点せず、予想を実際の意味につなげます。</p><p>絵本は初めからすべて自由に読めます。「イメージを見た」は正解・習得の記録には加えません。問題の前には元の語の意味も確認できます。</p><ol><li>基本・中級の絵本で、接頭辞のイメージを見ます。</li><li>元の英単語を知らなければ「意味を見てみる」で確認。</li><li>選択肢をタップして解答。正解・分解・実際の意味を確かめます。</li><li>復習画面で、苦手な語や時刻が来た語を思い出します。</li></ol><p>キーボードのTabで選び、Enterまたはスペースでボタンを押せます。音声は端末の英語読み上げ機能を使います。音声OFFにすると手動再生も停止します。</p><p>学習記録は端末内だけに保存します。他の端末への同期はありません。個人名・ログイン・有料APIは不要です。</p><p>最初はインターネットで教材を読み込みます。対応ブラウザでは準備完了後にオフラインでも使えます。英語音声のオフライン利用は端末によります。</p></section><section class="panel"><h2>4段階とMVP 14項目</h2><p>基本8項目、中級6項目を導入し、応用は同じ14項目の混合問題、発展は例外を扱います。基本・中級の絵本は初めから自由に読めます。14項目で各1問正解すると応用、応用で4問正解すると発展が開きます。これは学習の入口の条件で、習得認定ではありません。</p><p>元パックの43項目・179語を保持し、初版は66語を編集点検。56語を問題候補、10語を説明カードに限定しています。biplaneは接頭辞の意味問題のみです。</p><p class="warning">暫定教材です。全語の個別辞書確認、難易度、授業での有効性は未検証です。英検・CEFRなどの公式認定語彙ではありません。</p><p>データの正解は許可リストだけを使用。自由な接頭辞の合成や、自動翻訳による正解は作りません。quiz_eligible=false、対象外項目、レビュー保留語は出題しません。</p></section><details class="panel"><summary>要レビューの10語と理由</summary>${holds.map(w=>`<p><strong>${esc(w.word)}</strong>：${esc(data.editorial.words[w.word].reason_ja)}</p>`).join('')}<p>ほかの出題語も個別辞書照合と教員レビューは完了していません。元データのreview_statusは変更していません。</p></details><details class="panel"><summary>参考資料・権利・確認範囲</summary><p>日本語の説明と図は独自に作成。共通キャラクターと4場面の画像は新規AI生成。画像生成の記録はdata/image-assets.jsonに保存しています。外部サイトの本文・例文・画像・音声は転載していません。</p>${data.editorial.references.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(r.url).pathname.split('/').pop())}</a>：${esc(r.scope)}</p>`).join('')}<p>検索結果を手がかりに一部語義を確認した範囲で、辞書本文の全件照合ではありません。</p><a href="data/editorial.json">編集点検データ（JSON）</a> / <a href="docs/REVIEW.md">レビュー記録</a></details>`);}
function route(){if(!data)return;stop();session=null;const [page,id]=(location.hash.slice(1)||'home').split('/');view=page;if(page==='stage')stage(Number(id));else if(page==='lesson')lesson(id);else if(page==='review')records(true);else if(page==='records')records(false);else if(page==='guide')guide();else if(page==='images')gallery();else home();}
app.onclick=e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='speak')return speak(b.dataset.word);if(a==='practice')practice(b.dataset.prefix);else if(a==='mixed')mixed(Number(b.dataset.stage));else if(a==='basehint'){session.hint=true;drawSession();}else if(a==='know'){session.phase='question';drawSession();}else if(a==='answer')answer(Number(b.dataset.index));else if(a==='next'){const s=session;if(!s?.answered)return;s.index++;s.answered=false;s.hint=false;s.chosen=null;s.phase=s.qs[s.index]?.mode==='trap'?'question':'base';drawSession();}else if(a.startsWith('review'))reviewStart(a,b.dataset.item);};
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=normalize(JSON.parse(e.newValue));state.attempts=merge(state.attempts,next.attempts);state.seen=[...new Set([...state.seen,...next.seen])];if(!session)route();}catch{}});
async function init(){try{const files=['prefixes','words','mvp','stages','pitfalls','editorial','stories'];const results=await Promise.all(files.map(async name=>{const r=await fetch(`./data/${name}.json`);if(!r.ok)throw Error(name);return [name,await r.json()];}));data=Object.fromEntries(results);load();soundUI();route();if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;$('#notice').textContent=storageFailed?'この環境では学習記録を保存できません。':'オフラインの準備ができました（音声は端末によります）。';}catch{$('#notice').textContent='オフライン保存が使えません。接続したまま学習できます。';}}}catch{setView('<h1>教材を読み込めませんでした</h1><p>インターネット接続を確認し、再読み込みしてください。ファイルを直接開いた場合は、GitHub PagesなどHTTP(S)で開いてください。</p>'+btn('reload','再読み込み','primary'));app.onclick=e=>{if(e.target.closest('[data-action="reload"]'))location.reload();};}}
init();
